attribute vec3 aO; attribute float aT, aK, aS; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 0.50){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){
        float S = .75*aS; vP = position.xy/.75*.75; vP = position.xy*.75;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
      } else {
        vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
        float Wd = .45*aS, H = 1.2*aS;
        vP = position.xy;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*position.x*Wd + vec3(0., (position.y*.5 + .5)*2.*H + .1, 0.), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec3 outc;
      if (vK < .5){
        float t = vU/0.50, r = length(vP);
        float R = mix(.12, .6, 1. - pow(1. - t, 3.)), f = pow(1. - t, 1.6);
        float ring = exp(-pow(abs(r - R)/.018, 2.4)), hot = lcore(r - R, .005);
        float flash = exp(-r*r*18.)*(vU < .033 ? 1. : 0.);
        outc = (uOrange*(ring*.9 + flash*.8) + mix(uGold, vec3(1.), .4)*hot*.6)*f*smoothstep(.75, .66, r);
      } else {
        // three thin streaks rising and thinning out; soft everywhere, zero at the quad edges
        float x = vP.x, y = vP.y*.5 + .5, t = vU/0.50;
        float lum = 0.;
        for (int i=0;i<3;i++){
          float fi = float(i), ox = (fi - 1.)*.42, dl = fi == 1. ? 0. : .05;
          float tt = clamp((vU - dl)/.3, 0., 1.);
          float head = tt*1.1, tail = head - .45;
          float seg = smoothstep(tail, tail + .25, y)*smoothstep(head + .02, head - .12, y);
          lum += exp(-pow((x - ox)/.05, 2.))*seg*(1. - smoothstep(.55, 1., t))*(fi == 1. ? 1. : .6);
        }
        outc = mix(uOrange, uGold, .5)*lum*.7*smoothstep(1., .8, abs(x))*smoothstep(1., .9, y);
      }
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

